const optimizedPath=(value,target=1280)=>{const item=imageRecord(value);if(!item.allowed)return "";const path=item.derivatives?(target<=640?item.derivatives.webp640:item.derivatives.webp1280):`assets/optimized/${item.optimizedStem}-${Math.min(item.width,target)}.webp`;if(isLocalAsset(path))usedImagePaths.add(path);return path;};
