function archivesPage(){const route="/archives";const highlights=stories.filter(item=>item.status==="published"&&item.featured);const featured=highlights.length?`<section class="archive-featured section"><div class="home-section-intro"><div><p class="overline">From the archive</p><h2>Featured and recently added stories</h2></div><a class="text-action" href="${href(route,"/archives/all")}">Browse all stories →</a></div><div class="editorial-panel-grid editorial-panel-grid--stories">${highlights.map(item=>editorialPanel(route,item,{kind:"story",variant:"portrait"})).join("")}</div></section>`:"";const categories=archiveCategories.length?`<section class="archive-categories section"><div class="archive-collections-heading"><p class="overline">Explore the collections</p><h2>Follow heritage through connected fields of inquiry.</h2></div><div class="archive-category-grid">${archiveCategories.map(item=>archiveCategoryPanel(route,item)).join("")}</div></section>`:"";const search=`<section class="archive-global-search section"><form action="${href(route,"/archives/all")}" method="get"><label for="archive-discovery-search">Search the Archive</label><div><input id="archive-discovery-search" name="q" type="search" placeholder="Search places, objects, people or traditions"><button class="button primary">Search <span aria-hidden="true">→</span></button></div></form></section>`;return shell({route,active:"archives",title:"Archives | Virsapur",description:"Explore Virsapur’s curated Archive collections and researched stories about Pakistan’s heritage.",image:archiveCategories[0]?.featuredImage||"assets/archive-architecture.webp",main:pageHero(route,{eyebrow:"Places · objects · cultural memory",title:"Stories & Archives",intro:"Explore researched stories through collections that connect place, material culture and living memory.",variant:"functional"})+search+categories+featured+`<section class="archive-browse-callout section"><p class="overline">Complete collection</p><h2>Looking for a specific place, object or story?</h2><a class="button primary" href="${href(route,"/archives/all")}">Browse all stories <span aria-hidden="true">→</span></a><p><a class="text-action" href="${href(route,"/archives/title-index")}">Story title index →</a> · <a class="text-action" href="${href(route,"/archives/places")}">Heritage Place index →</a></p></section>`});}
