const sitemapRoutes=routeManifest.filter(i=>i.sitemap&&i.indexable).map(i=>i.route);
const sitemapGroups=new Map();for(const item of routeManifest.filter(i=>i.sitemap&&i.indexable)){const group=item.type==="story"?"articles":item.type==="heritage-place"?"heritage":item.route.startsWith("/tours")||item.type==="programme"?"tours":item.route==="/whats-on"?"events":"pages";if(!sitemapGroups.has(group))sitemapGroups.set(group,[]);sitemapGroups.get(group).push(item.route);}
for(const [name,routes]of sitemapGroups)await writeFile(join(outputRoot,`sitemap-${name}.xml`),`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${routes.map(r=>`<url><loc>${esc(canonical(r))}</loc></url>`).join("")}</urlset>\n`);
await writeFile(join(outputRoot,"sitemap.xml"),`<?xml version="1.0" encoding="UTF-8"?>\n<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${[...sitemapGroups.keys()].map(name=>`<sitemap><loc>${esc(siteOrigin)}/sitemap-${name}.xml</loc></sitemap>`).join("")}</sitemapindex>\n`);
await writeFile(join(outputRoot,"robots.txt"),studioMode?"User-agent: *\nDisallow: /\n":`User-agent: *\nAllow: /\nSitemap: ${siteOrigin}/sitemap.xml\n`);
