function profileBookingsPage(){const route="/profile/bookings";const content=`<header class="profile-topbar"><div><p class="overline">OFFICIAL HERITAGE TRIPS</p><h1>My bookings</h1></div><a class="button secondary" href="${href(route,"/whats-on")}">Explore trips</a></header><p class="trip-page-intro">Track official trip requests and see when the Virsapur team confirms or declines your seats.</p><section class="member-bookings" data-member-bookings data-login-url="${href(route,"/login")}" data-whats-on-url="${href(route,"/whats-on")}"><p class="form-note" role="status" aria-live="polite" data-member-bookings-status>Loading your booking requests…</p><div class="member-bookings-list" data-member-bookings-list></div></section>`;const main=memberArea(route,"bookings",content)+`<script type="module" src="${asset(route,"components/profile-bookings.js")}?v=booking-stripe-payment-v1"></script>`;return shell({route,active:"",title:"My Bookings | Virsapur",description:"Track approval status for your official Virsapur heritage trip requests.",main,status:"published",schema:[]});}
